  tableName=DatabaseTestHelper.getTestTableName("IT");
  executeWithRetry(JdbcIOIT::createTable);
  try {
    tableSize=DatabaseTestHelper.getPostgresTableSize(dataSource,tableName).orElse(0L);
    settings=InfluxDBSettings.builder().withHost(options.getInfluxHost()).withDatabase(options.getInfluxDatabase()).withMeasurement(options.getInfluxMeasurement()).get();
  } catch (SecurityException e) {
    throw new Exception("Security manager prevented access to environment variables", e);
  }
}
